    Record rcall (p : Z) (A : AS MI) (M : mem) (model : Model) (R : bvmap 5 word) : Prop := RCALL {
      rc_ai : ainv MI A M model;
      rc_ms : mstd model;
      rc_fs : m_fs model = m_fs model0;
      rc_fds : m_fds model = m_fds model0;
      rc_regs : base_ok R;
      rc_s0 : getr R 8%bv = Z_to_bv 64 obj;
      rc_s1 : getr R 9%bv = Z_to_bv 64 p;
      rc_s2 : getr R 18%bv = Z_to_bv 64 bc;
      rc_s3 : getr R 19%bv = Z_to_bv 64 key;
      rc_a0 : getr R 10%bv = Z_to_bv 64 obj;
      rc_a1 : getr R 11%bv = Z_to_bv 64 (bseq_next bc);
      rc_ra : getr R 1%bv = Z_to_bv 64 REHR;
      rc_frame : frame M;
      rc_def : defined M (sp - SS) SS;
      rc_p0 : 0 < p; rc_pc : p + 24 <= alloc_ceiling; rc_pal : p mod 16 = 0;
      rc_plive : In (p, 24) (live MI A);
      rc_pnew : ~ In p (map fst (live MI A0));
      rc_n0 : cell8 SEGS M p 0;
      rc_nh : cell8 SEGS M (p + 8) key;
      rc_nk : cell4 SEGS M (p + 16) key;
      rc_nv : cell4 SEGS M (p + 20) 0;
      rc_pdef : defined M p 24;
      rc_eff : eff MI A0 A M0 M W (fun a => p <= a < p + 24);
      rc_ladd : live_add p 24 (live MI A0) (live MI A);
      rc_U : umapx MI 24 (nval24 SEGS) A M obj bl bc ents;
      rc_grow : bc = 0 \/ Zlength ents = bc
    }.

    Lemma phaseR1 : forall (fx1 : FPState) p A M model R,
      core p A M model R -> getr R 18%bv = Z_to_bv 64 bc ->
      frm_zero (@fp_csr fx1) -> fholds fx1 14%bv (ieee (Zlength ents + 1)) -> fholds fx1 15%bv one32 ->
      (bc = 0 \/ Zlength ents = bc) ->
      eff MI A0 A M0 M W (fun a => p <= a < p + 24) -> live_add p 24 (live MI A0) (live MI A) ->
      umapx MI 24 (nval24 SEGS) A M obj bl bc ents -> ro_clear L M ->
      (forall (fx2 : FPState) M' R', frm_zero (@fp_csr fx2) -> rcall p A M' model R' -> srealizes SEGS (cfg fx2 R' REH M' model) K) ->
      srealizes SEGS (cfg fx1 R RH_PC M model) K.
